//! Owned clip updates for animated transform owners.
use vexel_geometry::{affine_compose, affine_identity, affine_map_point};
use vexel_scene::{
    Clip, ClipGeometry, Diagnostic, Edge, ErrorKind, EvaluatedFrame, LimitKind, Result, SceneView,
    Shape, ShapeId, TransformFrame, TransformId, WorkControl, WorkKind,
};

const CLIP_COPY_MAX_BYTES: usize = 64 * 1024 * 1024;
const CLIP_CHAIN_MAX: usize = 128;
const CLIP_OWNER_DEPTH_MAX: usize = 64;
const TRANSFORM_WORK_MAX: usize = 50_000_000;

fn invalid(offset: usize) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::InvalidArgument,
        offset,
    }
}
fn limit(kind: LimitKind) -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(kind),
        offset: 0,
    }
}
fn arithmetic() -> Diagnostic {
    limit(LimitKind::Arithmetic)
}
fn oom() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::OutOfMemory,
        offset: 0,
    }
}
fn add(a: usize, b: usize) -> Result<usize> {
    a.checked_add(b).ok_or_else(arithmetic)
}
fn bytes<T>(count: usize) -> Result<usize> {
    count
        .checked_mul(std::mem::size_of::<T>())
        .ok_or_else(arithmetic)
}

fn poll(control: &mut dyn WorkControl, kind: WorkKind, count: usize) -> Result<()> {
    let units = u64::try_from(count).map_err(|_| arithmetic())?;
    control.charge(kind, units).map_err(|stop| Diagnostic {
        kind: match stop {
            vexel_scene::Stop::Canceled => ErrorKind::Canceled,
            vexel_scene::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
            vexel_scene::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
        },
        offset: 0,
    })
}
fn add_work(work: &mut usize, count: usize) -> Result<()> {
    if *work >= TRANSFORM_WORK_MAX || count > TRANSFORM_WORK_MAX - *work {
        *work = TRANSFORM_WORK_MAX;
        return Err(limit(LimitKind::Work));
    }
    *work += count;
    Ok(())
}
fn charge(
    control: &mut dyn WorkControl,
    kind: WorkKind,
    count: usize,
    work: &mut usize,
) -> Result<()> {
    add_work(work, count)?;
    poll(control, kind, count)
}
fn clip_inverse(m: vexel_scene::Affine) -> Option<vexel_scene::Affine> {
    let det = m.a * m.d - m.b * m.c;
    if !det.is_finite() || det == 0.0 {
        return None;
    }
    let k = 1.0 / det;
    let out = vexel_scene::Affine {
        a: m.d * k,
        b: -m.b * k,
        c: -m.c * k,
        d: m.a * k,
        e: (m.c * m.f - m.d * m.e) * k,
        f: (m.b * m.e - m.a * m.f) * k,
    };
    vexel_geometry::affine_valid(out).then_some(out)
}

fn node_product(
    transforms: &[TransformFrame],
    target: TransformId,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<(vexel_scene::Affine, vexel_scene::Affine)> {
    let mut chain = [None; CLIP_CHAIN_MAX];
    let mut count = 0;
    let mut node = Some(target);
    while let Some(id) = node {
        if count == CLIP_CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(0));
        }
        charge(control, WorkKind::ClipChain, 1, work)?;
        chain[count] = Some(id);
        count += 1;
        node = transforms[id.index()].parent;
    }
    let mut full = affine_identity();
    let mut before_suffix = affine_identity();
    while count != 0 {
        poll(control, WorkKind::ClipChain, 1)?;
        count -= 1;
        let id = chain[count].ok_or_else(|| invalid(0))?;
        let transform = transforms[id.index()];
        let local = affine_compose(transform.motion, transform.attribute)
            .ok_or_else(|| invalid(transform.source_offset))?;
        if id == target {
            before_suffix =
                affine_compose(full, local).ok_or_else(|| invalid(transform.source_offset))?;
        }
        let with_suffix = affine_compose(local, transform.suffix)
            .ok_or_else(|| invalid(transform.source_offset))?;
        full = affine_compose(full, with_suffix).ok_or_else(|| invalid(transform.source_offset))?;
    }
    Ok((full, before_suffix))
}

fn shape_has_node(
    shape: &Shape,
    transforms: &[TransformFrame],
    target: TransformId,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<bool> {
    let mut node = shape.source.transform_node;
    let mut depth = 0;
    while let Some(id) = node {
        if depth >= CLIP_CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(shape.source.element.start));
        }
        charge(control, WorkKind::ClipChain, 1, work)?;
        if id == target {
            return Ok(true);
        }
        node = transforms[id.index()].parent;
        depth += 1;
    }
    Ok(false)
}

fn bounds_for_node(
    shapes: &[Shape],
    edges: &[Edge],
    transforms: &[TransformFrame],
    target: TransformId,
    inverse: vexel_scene::Affine,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<[f64; 4]> {
    let mut bounds: Option<[f64; 4]> = None;
    for shape in shapes {
        poll(control, WorkKind::ReferenceProbe, 1)?;
        if !shape_has_node(shape, transforms, target, control, work)? {
            continue;
        }
        let segment = shape
            .edges
            .slice(edges)
            .ok_or_else(|| invalid(shape.source.element.start))?;
        for edge in segment {
            charge(control, WorkKind::ClipEdge, 1, work)?;
            for point in [edge.a, edge.b] {
                let local = affine_map_point(inverse, point)
                    .ok_or_else(|| invalid(shape.source.element.start))?;
                match &mut bounds {
                    Some(b) => {
                        b[0] = b[0].min(local.x);
                        b[1] = b[1].min(local.y);
                        b[2] = b[2].max(local.x);
                        b[3] = b[3].max(local.y);
                    }
                    None => bounds = Some([local.x, local.y, local.x, local.y]),
                }
            }
        }
    }
    bounds.ok_or_else(|| invalid(0))
}

fn update_clip_owner(
    shapes: &[Shape],
    clips: &mut [Clip],
    node: TransformId,
    full_inverse: vexel_scene::Affine,
    before_suffix_inverse: vexel_scene::Affine,
    bounds: Option<[f64; 4]>,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<()> {
    for shape in shapes {
        add_work(work, CLIP_OWNER_DEPTH_MAX)?;
        poll(control, WorkKind::ClipChain, 1)?;
        let mut current = shape.clip;
        let mut depth = 0;
        while let Some(id) = current {
            if depth >= CLIP_OWNER_DEPTH_MAX || id.index() >= clips.len() {
                return Err(invalid(shape.source.element.start));
            }
            poll(control, WorkKind::ClipChain, 1)?;
            let clip = &mut clips[id.index()];
            if clip.owner_node == Some(node) {
                clip.user_inverse = if clip.owner_before_suffix {
                    before_suffix_inverse
                } else {
                    full_inverse
                };
                if let Some(b) = bounds {
                    if clip.object_bounding_box
                        && b.into_iter().all(f64::is_finite)
                        && b[2] >= b[0]
                        && b[3] >= b[1]
                    {
                        clip.bounds = b;
                    }
                }
            }
            current = clip.parent;
            depth += 1;
        }
    }
    Ok(())
}

fn update_clip_shape(
    shapes: &[Shape],
    edges: &[Edge],
    transforms: &[TransformFrame],
    clips: &mut [Clip],
    shape: &Shape,
    update_bounds: bool,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<()> {
    let mut node = shape.source.transform_node;
    let mut depth = 0;
    while let Some(id) = node {
        poll(control, WorkKind::ClipChain, 1)?;
        if depth >= CLIP_CHAIN_MAX || id.index() >= transforms.len() {
            return Err(invalid(shape.source.element.start));
        }
        let (full, before_suffix) = node_product(transforms, id, control, work)?;
        let full_inverse = clip_inverse(full).ok_or_else(|| invalid(shape.source.element.start))?;
        let attribute_inverse =
            clip_inverse(before_suffix).ok_or_else(|| invalid(shape.source.element.start))?;
        let bounds = if update_bounds {
            Some(bounds_for_node(
                shapes,
                edges,
                transforms,
                id,
                full_inverse,
                control,
                work,
            )?)
        } else {
            None
        };
        update_clip_owner(
            shapes,
            clips,
            id,
            full_inverse,
            attribute_inverse,
            bounds,
            control,
            work,
        )?;
        node = transforms[id.index()].parent;
        depth += 1;
    }
    Ok(())
}

fn clone_clip_table(
    view: SceneView<'_>,
    control: &mut dyn WorkControl,
    _work: &mut usize,
) -> Result<Vec<Clip>> {
    let mut estimate = bytes::<Clip>(view.clips.len())?;
    for clip in view.clips {
        poll(control, WorkKind::ClipChild, 1)?;
        estimate = add(estimate, bytes::<Edge>(clip.geometry.edges.len())?)?;
        estimate = add(
            estimate,
            bytes::<vexel_scene::ClipChild>(clip.geometry.shapes.len())?,
        )?;
    }
    if estimate > CLIP_COPY_MAX_BYTES {
        return Err(limit(LimitKind::Animation));
    }
    let mut output = Vec::new();
    output
        .try_reserve_exact(view.clips.len())
        .map_err(|_| oom())?;
    for source in view.clips {
        poll(control, WorkKind::ClipChild, 1)?;
        let mut edges = Vec::new();
        edges
            .try_reserve_exact(source.geometry.edges.len())
            .map_err(|_| oom())?;
        for edge in &source.geometry.edges {
            poll(control, WorkKind::ClipEdge, 1)?;
            edges.push(*edge);
        }
        let mut shapes = Vec::new();
        shapes
            .try_reserve_exact(source.geometry.shapes.len())
            .map_err(|_| oom())?;
        for child in &source.geometry.shapes {
            poll(control, WorkKind::ClipChild, 1)?;
            shapes.push(*child);
        }
        output.push(Clip {
            geometry: ClipGeometry { edges, shapes },
            parent: source.parent,
            owner_node: source.owner_node,
            owner_before_suffix: source.owner_before_suffix,
            object_bounding_box: source.object_bounding_box,
            bounds: source.bounds,
            user_inverse: source.user_inverse,
        });
    }
    let actual = actual_clip_capacity(&output, control, _work)?;
    if actual > CLIP_COPY_MAX_BYTES {
        return Err(limit(LimitKind::Animation));
    }
    Ok(output)
}

fn actual_clip_capacity(
    clips: &Vec<Clip>,
    control: &mut dyn WorkControl,
    _work: &mut usize,
) -> Result<usize> {
    let mut total = clips
        .capacity()
        .checked_mul(std::mem::size_of::<Clip>())
        .ok_or_else(arithmetic)?;
    for clip in clips {
        poll(control, WorkKind::ClipChild, 1)?;
        let edges = clip
            .geometry
            .edges
            .capacity()
            .checked_mul(std::mem::size_of::<Edge>())
            .ok_or_else(arithmetic)?;
        let shapes = clip
            .geometry
            .shapes
            .capacity()
            .checked_mul(std::mem::size_of::<vexel_scene::ClipChild>())
            .ok_or_else(arithmetic)?;
        total = add(total, add(edges, shapes)?)?;
    }
    Ok(total)
}

pub(crate) fn clone_clips_for_overlay(
    view: SceneView<'_>,
    control: &mut dyn WorkControl,
) -> Result<Vec<Clip>> {
    let mut work = 0;
    clone_clip_table(view, control, &mut work)
}

pub(crate) fn update_clip_table_for_shape(
    transforms: &[TransformFrame],
    shapes: &[Shape],
    edges: &[Edge],
    clips: &mut [Clip],
    index: usize,
    update_bounds: bool,
    control: &mut dyn WorkControl,
    work: &mut usize,
) -> Result<()> {
    let shape = shapes.get(index).ok_or_else(|| invalid(0))?;
    update_clip_shape(
        shapes,
        edges,
        transforms,
        clips,
        shape,
        update_bounds,
        control,
        work,
    )
}

/// Update clip owner inverses and object-bounding-box bounds for one shape's
/// complete instance-specific transform ancestry. Publication is atomic.
pub fn update_animation_clips(
    frame: &mut EvaluatedFrame<'_>,
    shape: ShapeId,
    update_bounds: bool,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let view = frame.view();
    if view.clips.is_empty() {
        return Err(invalid(0));
    }
    control.checkpoint().map_err(|s| match s {
        vexel_scene::Stop::Canceled => Diagnostic {
            kind: ErrorKind::Canceled,
            offset: 0,
        },
        vexel_scene::Stop::Limit => limit(LimitKind::Work),
        vexel_scene::Stop::Overflow => arithmetic(),
    })?;
    let mut work = 0;
    let mut clips = clone_clip_table(view, control, &mut work)?;
    let shapes = view.shapes;
    let edges = view.edges;
    let transforms = view.transforms;
    let selected = view.shape(shape).ok_or_else(|| invalid(0))?;
    update_clip_shape(
        shapes,
        edges,
        transforms,
        &mut clips,
        selected,
        update_bounds,
        control,
        &mut work,
    )?;
    frame.replace_clips(clips, control)
}

#[cfg(test)]
#[path = "clip_tests.rs"]
mod tests;
use super::*;

pub(super) fn apply_value(
    view: SceneView<'_>,
    t: &Track,
    item: OverlayItem,
    edges: &mut [Edge],
    colors: &mut [[u8; 4]],
    shapes: &mut [Shape],
    fills: &mut [Paint],
    _strokes: &mut [Paint],
    world: &[Affine],
    control: &mut dyn WorkControl,
    work: &mut usize,
    ce: &mut bool,
    cc: &mut bool,
    cs: &mut bool,
    cf: &mut bool,
    _csp: &mut bool,
    clip_shape_flags: &mut [bool],
) -> Result<()> {
    let mut descendant = false;
    let mut direct = false;
    let target_end = t
        .target
        .offset
        .checked_add(t.target.length)
        .ok_or_else(arithmetic)?;
    for (i, shape) in shapes.iter_mut().enumerate() {
        charge(control, 1)?;
        count_work(work, 1)?;
        let mut node = shape.source.transform_node;
        let mut depth = 0;
        let mut in_target = shape.source.element.start >= t.target.offset
            && shape.source.element.start < target_end;
        while !in_target {
            let Some(id) = node else {
                break;
            };
            if depth >= CHAIN_MAX {
                return Err(limit(LimitKind::Animation));
            }
            let n = view
                .transform(id)
                .ok_or_else(|| invalid(t.element.offset))?;
            charge(control, 1)?;
            count_work(work, 1)?;
            if n.source_offset >= t.target.offset && n.source_offset < target_end {
                in_target = true;
            }
            node = n.parent;
            depth += 1;
        }
        if !in_target {
            continue;
        }
        descendant = true;
        if t.attribute == Attribute::D {
            return Err(diag(ErrorKind::Unsupported, t.element.offset));
        }
        let is_direct = if let Some(id) = shape.source.transform_node {
            charge(control, 1)?;
            count_work(work, 1)?;
            view.transform(id)
                .ok_or_else(|| invalid(t.element.offset))?
                .source_offset
                == t.target.offset
        } else {
            shape.source.element.start == t.target.offset
        };
        if !is_direct {
            continue;
        }
        direct = true;
        match t.attribute {
            Attribute::Fill if item.value.kind == ValueKind::Color => {
                let r = shape.edges;
                if r.end().is_none_or(|e| e > colors.len()) {
                    return Err(invalid(t.element.offset));
                }
                count_work(work, r.count)?;
                for c in &mut colors[r.first..r.first + r.count] {
                    charge(control, 1)?;
                    *c = item.value.rgba;
                }
                *cc = true;
            }
            Attribute::Stroke if item.value.kind == ValueKind::Color => {
                shape.stroke.rgba = item.value.rgba;
                *cs = true;
            }
            Attribute::Opacity | Attribute::FillOpacity if item.value.kind == ValueKind::Number => {
                let op = item.value.number[0].clamp(0., 1.);
                let r = shape.edges;
                if r.end().is_none_or(|e| e > colors.len()) {
                    return Err(invalid(t.element.offset));
                }
                count_work(work, r.count)?;
                for c in &mut colors[r.first..r.first + r.count] {
                    charge(control, 1)?;
                    c[3] = (f64::from(c[3]) * op + 0.5).floor() as u8;
                }
                *cc = true;
                if t.attribute == Attribute::Opacity {
                    shape.stroke.rgba[3] =
                        (f64::from(shape.stroke.rgba[3]) * op + 0.5).floor() as u8;
                    *cs = true;
                }
            }
            Attribute::StrokeOpacity if item.value.kind == ValueKind::Number => {
                let op = item.value.number[0].clamp(0., 1.);
                shape.stroke.rgba[3] = (f64::from(shape.stroke.rgba[3]) * op + 0.5).floor() as u8;
                *cs = true;
            }
            Attribute::StrokeWidth | Attribute::StrokeDashoffset
                if item.value.kind == ValueKind::Number =>
            {
                let v = item.value.number[0];
                if v.abs() > 1e6 || (t.attribute == Attribute::StrokeWidth && v < 0.) {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                if t.attribute == Attribute::StrokeWidth {
                    shape.stroke.width = v
                } else {
                    shape.stroke.dash_offset = v
                }
                *cs = true;
            }
            Attribute::D => return Err(diag(ErrorKind::Unsupported, t.element.offset)),
            Attribute::X
            | Attribute::Y
            | Attribute::Cx
            | Attribute::Cy
            | Attribute::Width
            | Attribute::Height
            | Attribute::Rx
            | Attribute::Ry
            | Attribute::R
                if item.value.kind == ValueKind::Number =>
            {
                if has_effect(view, i, control, work)? {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                let delta = item.value.number[0] - t.base_value.number[0];
                if !delta.is_finite() || delta.abs() > 1e6 {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                let mut local = affine_identity();
                match t.attribute {
                    Attribute::X | Attribute::Cx => local.e = delta,
                    Attribute::Y | Attribute::Cy => local.f = delta,
                    _ => {
                        let base = t.base_value.number[0];
                        if base <= 0. {
                            return Err(diag(ErrorKind::Unsupported, t.element.offset));
                        }
                        let scale = item.value.number[0] / base;
                        if !scale.is_finite() || scale < 0. || scale > 1e6 {
                            return Err(diag(ErrorKind::Unsupported, t.element.offset));
                        }
                        let inv = inverse(world[i], 1e-15)
                            .ok_or_else(|| diag(ErrorKind::Unsupported, t.element.offset))?;
                        let b = shape_bounds(shape, edges, inv, control, work)?;
                        if t.attribute == Attribute::Height || t.attribute == Attribute::Ry {
                            local.d = scale;
                            local.f = b[1] * (1. - scale);
                        } else {
                            let center = if t.attribute == Attribute::R {
                                (b[0] + b[2]) * 0.5
                            } else {
                                b[0]
                            };
                            local.a = scale;
                            local.e = center * (1. - scale);
                            if t.attribute == Attribute::R {
                                local.d = scale;
                                local.f = ((b[1] + b[3]) * 0.5) * (1. - scale);
                            }
                        }
                    }
                }
                if shape
                    .fill_paint
                    .is_some_and(|p| fills.get(p).is_some_and(|p| p.kind == PaintKind::Pattern))
                {
                    return Err(diag(ErrorKind::Unsupported, t.element.offset));
                }
                let matrix = affine_compose(
                    affine_compose(world[i], local).ok_or_else(|| invalid(0))?,
                    inverse(world[i], 1e-15).ok_or_else(|| invalid(0))?,
                )
                .ok_or_else(|| invalid(0))?;
                map_shape_edges(shape, matrix, edges, control, work)?;
                *ce = true;
                if !clip_shape_flags.is_empty() {
                    clip_shape_flags[i] = true;
                }
                if let Some(p) = shape.fill_paint.and_then(|n| fills.get_mut(n)) {
                    if p.object_bounding_box
                        && (p.kind == PaintKind::Linear || p.kind == PaintKind::Radial)
                    {
                        p.bounds = shape_bounds(
                            shape,
                            edges,
                            inverse(world[i], 1e-15).ok_or_else(|| invalid(0))?,
                            control,
                            work,
                        )?;
                        *cf = true;
                    }
                }
            }
            _ => return Err(diag(ErrorKind::Unsupported, t.element.offset)),
        }
    }
    if descendant && !direct {
        return Err(diag(ErrorKind::Unsupported, t.element.offset));
    }
    Ok(())
}

#include "shape_render.h"

#include "svg/animation/animation.h"
#include "svg/paint/paint.h"
#include "shape_render_animation_clips.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

#define ANIMATION_TRANSFORM_CHAIN_MAX 128U
#define ANIMATION_TRANSFORM_WORK_MAX 50000000U

static bool checked_bytes(size_t count, size_t stride, size_t *out)
{
    if (count != 0U && stride > SIZE_MAX / count) return false;
    *out = count * stride;
    return true;
}

static bool consume_work(size_t *work, size_t amount)
{
    if (work == NULL || *work >= ANIMATION_TRANSFORM_WORK_MAX ||
        amount > ANIMATION_TRANSFORM_WORK_MAX - *work) {
        if (work != NULL) *work = ANIMATION_TRANSFORM_WORK_MAX;
        return false;
    }
    *work += amount;
    return true;
}

static bool shape_in_target(const svg_shape_document *document,
                            size_t shape, const svg_anim_track *track,
                            size_t *work)
{
    if (document->shape_sources == NULL || shape >= document->shape_count ||
        track->target_length > SIZE_MAX - track->target_offset) return false;
    size_t target_end = track->target_offset + track->target_length;
    size_t offset = document->shape_sources[shape].offset;
    if (offset >= track->target_offset && offset < target_end) return true;
    size_t node_index = document->shape_sources[shape].transform_node;
    size_t visits = 0U;
    while (node_index != SVG_SHAPE_NO_TRANSFORM_NODE &&
           node_index < document->transform_node_count &&
           visits++ < ANIMATION_TRANSFORM_CHAIN_MAX) {
        if (!consume_work(work, 1U)) return false;
        const svg_shape_transform_frame *node =
            &document->transform_nodes[node_index];
        if (node->source_offset >= track->target_offset &&
            node->source_offset < target_end) return true;
        node_index = node->parent;
    }
    return false;
}

static bool shape_is_direct_target(const svg_shape_document *document,
                                   size_t shape, const svg_anim_track *track,
                                   size_t *work)
{
    if (document->shape_sources == NULL || shape >= document->shape_count)
        return false;
    size_t node_index = document->shape_sources[shape].transform_node;
    if (node_index < document->transform_node_count) {
        if (!consume_work(work, 1U)) return false;
        return document->transform_nodes[node_index].source_offset ==
               track->target_offset;
    }
    return node_index == SVG_SHAPE_NO_TRANSFORM_NODE &&
           document->shape_sources[shape].offset == track->target_offset;
}

static bool shape_target_node(const svg_shape_document *document, size_t shape,
                              const svg_anim_track *track, size_t *out_node,
                              size_t *work)
{
    if (document->shape_sources == NULL || shape >= document->shape_count ||
        document->transform_nodes == NULL || out_node == NULL) return false;
    size_t node_index = document->shape_sources[shape].transform_node;
    size_t visits = 0U;
    while (node_index != SVG_SHAPE_NO_TRANSFORM_NODE &&
           node_index < document->transform_node_count &&
           visits++ < ANIMATION_TRANSFORM_CHAIN_MAX) {
        if (!consume_work(work, 1U)) return false;
        const svg_shape_transform_frame *node =
            &document->transform_nodes[node_index];
        if (node->source_offset == track->target_offset) {
            *out_node = node_index;
            return true;
        }
        node_index = node->parent;
    }
    return false;
}

static bool shape_has_animated_effect_limit(const svg_shape_document *document,
                                            size_t shape, size_t *work,
                                            bool *found)
{
    *found = false;
    for (size_t index = 0U; index < document->opacity_group_count; ++index) {
        if (!consume_work(work, 1U)) return false;
        const svg_shape_opacity_group *group = &document->opacity_groups[index];
        if (shape >= group->first_shape && shape < group->end_shape &&
            (group->filter_index != SVG_SHAPE_NO_FILTER ||
             group->mask_index != SVG_SHAPE_NO_MASK)) {
            *found = true;
            return true;
        }
    }
    return true;
}

static bool shape_transform_product(const svg_shape_document *document,
                                    size_t shape, geom_affine *out,
                                    size_t *work)
{
    if (document->shape_sources == NULL || shape >= document->shape_count ||
        document->transform_nodes == NULL || out == NULL || work == NULL)
        return false;
    size_t chain[ANIMATION_TRANSFORM_CHAIN_MAX];
    size_t count = 0U;
    size_t node_index = document->shape_sources[shape].transform_node;
    while (node_index != SVG_SHAPE_NO_TRANSFORM_NODE) {
        if (node_index >= document->transform_node_count ||
            count == ANIMATION_TRANSFORM_CHAIN_MAX ||
            !consume_work(work, 1U)) return false;
        chain[count++] = node_index;
        node_index = document->transform_nodes[node_index].parent;
    }
    geom_affine result = geom_affine_identity();
    while (count != 0U) {
        const svg_shape_transform_frame *node =
            &document->transform_nodes[chain[--count]];
        geom_affine local, with_motion;
        if (!geom_affine_compose(node->attribute, node->suffix, &local) ||
            !geom_affine_compose(node->motion, local, &with_motion) ||
            !geom_affine_compose(result, with_motion, &result)) return false;
    }
    *out = result;
    return true;
}

static void scale_unit(double *value)
{
    if (*value < 0.0) *value = 0.0;
    if (*value > 1.0) *value = 1.0;
}

static bool affine_inverse(geom_affine value, geom_affine *out)
{
    double determinant = value.a * value.d - value.b * value.c;
    if (out == NULL || !isfinite(determinant) || fabs(determinant) < 1.0e-15)
        return false;
    double inverse = 1.0 / determinant;
    *out = (geom_affine){value.d * inverse, -value.b * inverse,
        -value.c * inverse, value.a * inverse,
        (value.c * value.f - value.d * value.e) * inverse,
        (value.b * value.e - value.a * value.f) * inverse};
    return geom_affine_valid(*out);
}

static bool transform_matrix(const svg_anim_track *track,
                             const svg_anim_value *value, geom_affine *out)
{
    double x = value->number[0], y = value->number[1];
    if (!isfinite(x) || !isfinite(y) || fabs(x) > 1000000.0 ||
        fabs(y) > 1000000.0) return false;
    geom_affine matrix = geom_affine_identity();
    if (track->transform_type == SVG_ANIM_TRANSFORM_TRANSLATE) {
        matrix.e = x;
        matrix.f = y;
    } else if (track->transform_type == SVG_ANIM_TRANSFORM_SCALE) {
        matrix.a = x;
        matrix.d = value->number[3] >= 2.0 ? y : x;
    } else if (track->transform_type == SVG_ANIM_TRANSFORM_ROTATE) {
        double angle = x * 0.017453292519943295769;
        double cosine = cos(angle), sine = sin(angle);
        if (!isfinite(cosine) || !isfinite(sine)) return false;
        matrix = (geom_affine){cosine, sine, -sine, cosine, 0.0, 0.0};
        if (value->number[3] >= 3.0) {
            geom_affine to_center = geom_affine_identity();
            geom_affine from_center = geom_affine_identity();
            to_center.e = value->number[1];
            to_center.f = value->number[2];
            from_center.e = -value->number[1];
            from_center.f = -value->number[2];
            geom_affine intermediate;
            if (!geom_affine_compose(to_center, matrix, &intermediate) ||
                !geom_affine_compose(intermediate, from_center, &matrix)) return false;
        }
    } else {
        double angle = x * 0.017453292519943295769;
        double tangent = tan(angle);
        if (!isfinite(tangent) || fabs(tangent) > 1000000.0) return false;
        if (track->transform_type == SVG_ANIM_TRANSFORM_SKEW_X) matrix.c = tangent;
        else matrix.b = tangent;
    }
    *out = matrix;
    return geom_affine_valid(matrix);
}

static bool apply_matrix_to_shape(svg_shape_document *document, size_t shape,
                                  geom_affine matrix, size_t *work)
{
    size_t start = document->shape_edge_start[shape];
    size_t count = document->shape_edge_count[shape];
    if (start > document->edge_count || count > document->edge_count - start)
        return false;
    if (!consume_work(work, count)) return false;
    for (size_t index = start; index < start + count; ++index) {
        geom_edge *edge = &document->edges[index];
        geom_point first, second;
        if (!geom_affine_map_point(matrix, edge->a, &first) ||
            !geom_affine_map_point(matrix, edge->b, &second)) return false;
        edge->a = first;
        edge->b = second;
    }
    geom_affine inverse;
    if (document->shape_stroke_inverse != NULL) {
        if (!affine_inverse(matrix, &inverse)) return false;
        geom_affine composed;
        if (!geom_affine_compose(document->shape_stroke_inverse[shape], inverse,
                                 &composed)) return false;
        document->shape_stroke_inverse[shape] = composed;
    }
    svg_shape_paint *paint =
        svg_shape_paint_for_shape_mutable(document, shape);
    if (paint != NULL && paint->kind != SVG_SHAPE_PAINT_SOLID) {
        geom_affine composed;
        if (!affine_inverse(matrix, &inverse) ||
            !geom_affine_compose(paint->user_inverse, inverse,
                                 &composed)) return false;
        paint->user_inverse = composed;
    }
    return true;
}

static bool apply_geometry_matrix(svg_shape_document *document, size_t shape,
                                  geom_affine matrix, size_t *work)
{
    size_t start = document->shape_edge_start[shape];
    size_t count = document->shape_edge_count[shape];
    if (start > document->edge_count || count > document->edge_count - start)
        return false;
    if (!consume_work(work, count)) return false;
    for (size_t index = start; index < start + count; ++index) {
        geom_edge *edge = &document->edges[index];
        geom_point first, second;
        if (!geom_affine_map_point(matrix, edge->a, &first) ||
            !geom_affine_map_point(matrix, edge->b, &second)) return false;
        edge->a = first;
        edge->b = second;
    }
    return true;
}

static bool bounds_for_shape(const svg_shape_document *document, size_t shape,
                             geom_affine world_inverse, double bounds[4],
                             size_t *work)
{
    size_t start = document->shape_edge_start[shape];
    size_t count = document->shape_edge_count[shape];
    if (start > document->edge_count || count > document->edge_count - start ||
        count == 0U) return false;
    if (!consume_work(work, count)) return false;
    geom_point first_local;
    if (!geom_affine_map_point(world_inverse, document->edges[start].a,
                               &first_local)) return false;
    bounds[0] = bounds[2] = first_local.x;
    bounds[1] = bounds[3] = first_local.y;
    for (size_t index = start; index < start + count; ++index) {
        const geom_point world_points[2] = {document->edges[index].a,
                                            document->edges[index].b};
        for (size_t point = 0U; point < 2U; ++point) {
            geom_point local;
            if (!geom_affine_map_point(world_inverse, world_points[point],
                                       &local)) return false;
            double x = local.x, y = local.y;
            if (x < bounds[0]) bounds[0] = x;
            if (y < bounds[1]) bounds[1] = y;
            if (x > bounds[2]) bounds[2] = x;
            if (y > bounds[3]) bounds[3] = y;
        }
    }
    return true;
}

static bool refresh_object_paint_bounds(svg_shape_document *document,
                                        size_t shape,
                                        geom_affine world_transform,
                                        size_t *work)
{
    svg_shape_paint *paint =
        svg_shape_paint_for_shape_mutable(document, shape);
    if (paint == NULL) return true;
    if (!paint->object_bounding_box ||
        (paint->kind != SVG_SHAPE_PAINT_LINEAR &&
         paint->kind != SVG_SHAPE_PAINT_RADIAL)) return true;
    geom_affine inverse;
    double bounds[4];
    if (!affine_inverse(world_transform, &inverse) ||
        !bounds_for_shape(document, shape, inverse, bounds, work) ||
        bounds[2] <= bounds[0] || bounds[3] <= bounds[1]) return false;
    memcpy(paint->bounds, bounds, sizeof(bounds));
    return true;
}

static bool matrix_for_numeric(const svg_shape_document *document, size_t shape,
                               const svg_anim_track *track,
                               const svg_anim_value *value,
                               geom_affine world_transform,
                               geom_affine *world_delta,
                               size_t *work)
{
    if (value->kind != SVG_ANIM_VALUE_NUMBER || !isfinite(value->number[0]) ||
        !isfinite(track->base_value.number[0])) return false;
    double delta = value->number[0] - track->base_value.number[0];
    if (fabs(delta) > 1000000.0) return false;
    geom_affine local_matrix = geom_affine_identity();
    switch (track->attribute) {
    case SVG_ANIM_ATTR_X:
    case SVG_ANIM_ATTR_CX: local_matrix.e = delta; break;
    case SVG_ANIM_ATTR_Y:
    case SVG_ANIM_ATTR_CY: local_matrix.f = delta; break;
    case SVG_ANIM_ATTR_WIDTH:
    case SVG_ANIM_ATTR_RX:
    case SVG_ANIM_ATTR_R: {
        double bounds[4];
        geom_affine inverse;
        if (!(track->base_value.number[0] > 0.0) ||
            !affine_inverse(world_transform, &inverse) ||
            !bounds_for_shape(document, shape, inverse, bounds, work)) return false;
        double scale = value->number[0] / track->base_value.number[0];
        if (!isfinite(scale) || scale < 0.0 || scale > 1000000.0) return false;
        double center = track->attribute == SVG_ANIM_ATTR_R ?
                        (bounds[0] + bounds[2]) * 0.5 : bounds[0];
        local_matrix.a = scale;
        local_matrix.e = center * (1.0 - scale);
        if (track->attribute == SVG_ANIM_ATTR_R) {
            double center_y = (bounds[1] + bounds[3]) * 0.5;
            local_matrix.d = scale;
            local_matrix.f = center_y * (1.0 - scale);
        }
        break;
    }
    case SVG_ANIM_ATTR_HEIGHT:
    case SVG_ANIM_ATTR_RY: {
        double bounds[4];
        geom_affine inverse;
        if (!(track->base_value.number[0] > 0.0) ||
            !affine_inverse(world_transform, &inverse) ||
            !bounds_for_shape(document, shape, inverse, bounds, work)) return false;
        double scale = value->number[0] / track->base_value.number[0];
        if (!isfinite(scale) || scale < 0.0 || scale > 1000000.0) return false;
        double center = bounds[1];
        local_matrix.d = scale;
        local_matrix.f = center * (1.0 - scale);
        break;
    }
    default: return false;
    }
    geom_affine inverse, mapped;
    return geom_affine_valid(local_matrix) &&
        affine_inverse(world_transform, &inverse) &&
        geom_affine_compose(world_transform, local_matrix, &mapped) &&
        geom_affine_compose(mapped, inverse, world_delta);
}

static bool apply_transform_track(svg_shape_document *document,
                                  const svg_anim_track *track,
                                  const svg_anim_overlay_item *item,
                                  bool *transform_seen,
                                  geom_affine *world_transforms,
                                  size_t *work)
{
    if (!item->active) return true;
    geom_affine animation = geom_affine_identity();
    if (track->kind == SVG_ANIM_KIND_TRANSFORM) {
        if (!transform_matrix(track, &item->value, &animation)) return false;
    } else if (track->kind == SVG_ANIM_KIND_MOTION) {
        if (item->value.kind != SVG_ANIM_VALUE_MOTION) return false;
        double angle = item->value.number[2] * 0.017453292519943295769;
        if (!isfinite(angle) || !isfinite(item->value.number[0]) ||
            !isfinite(item->value.number[1])) return false;
        geom_affine rotate = {cos(angle), sin(angle), -sin(angle),
                              cos(angle), 0.0, 0.0};
        geom_affine translate = {1.0, 0.0, 0.0, 1.0,
                                 item->value.number[0], item->value.number[1]};
        if (!geom_affine_compose(translate, rotate, &animation)) return false;
    } else return false;

    bool found = false;
    for (size_t node = 0U; node < document->transform_node_count; ++node) {
        if (!consume_work(work, 1U)) return false;
        svg_shape_transform_frame *target = &document->transform_nodes[node];
        if (target->source_offset != track->target_offset) continue;
        found = true;
        if (track->kind == SVG_ANIM_KIND_TRANSFORM) {
            if (track->additive_sum || transform_seen[node]) {
                if (!geom_affine_compose(target->attribute, animation,
                                         &target->attribute)) return false;
            } else target->attribute = animation;
            transform_seen[node] = true;
        } else if (!geom_affine_compose(target->motion, animation,
                                       &target->motion)) return false;
    }
    if (!found) return true;

    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
        if (!consume_work(work, 1U)) return false;
        size_t target_node = SVG_SHAPE_NO_TRANSFORM_NODE;
        if (!shape_target_node(document, shape, track, &target_node, work)) {
            if (*work >= ANIMATION_TRANSFORM_WORK_MAX) return false;
            continue;
        }
        bool effect_limited = false;
        if (!shape_has_animated_effect_limit(document, shape, work,
                                             &effect_limited) ||
            effect_limited) return false;
        geom_affine next_world, old_inverse, delta;
        if (!shape_transform_product(document, shape, &next_world, work) ||
            !affine_inverse(world_transforms[shape], &old_inverse) ||
            !geom_affine_compose(next_world, old_inverse, &delta) ||
            !apply_matrix_to_shape(document, shape, delta, work)) return false;
        world_transforms[shape] = next_world;
        if (document->has_clips && document->clips != NULL &&
            !raster_animation_clips_update(document, shape, true, work,
                                          ANIMATION_TRANSFORM_WORK_MAX))
            return false;
        (void)target_node;
    }
    return true;
}

static bool apply_track(svg_shape_document *document,
                        const svg_anim_track *track,
                        const svg_anim_overlay_item *item,
                        bool *transform_seen,
                        geom_affine *world_transforms,
                        size_t *work)
{
    if (!item->active) return true;
    if (track->kind == SVG_ANIM_KIND_TRANSFORM ||
        track->kind == SVG_ANIM_KIND_MOTION)
        return apply_transform_track(document, track, item, transform_seen,
                                     world_transforms, work);
    bool descendant_found = false;
    bool direct_found = false;
    for (size_t shape = 0U; shape < document->shape_count; ++shape) {
        if (!consume_work(work, 1U)) return false;
        bool in_target = shape_in_target(document, shape, track, work);
        if (*work >= ANIMATION_TRANSFORM_WORK_MAX) return false;
        if (!in_target) continue;
        descendant_found = true;
        if (track->attribute == SVG_ANIM_ATTR_D) return false;
        bool direct_target = shape_is_direct_target(document, shape, track, work);
        if (*work >= ANIMATION_TRANSFORM_WORK_MAX) return false;
        if (!direct_target) continue;
        direct_found = true;
        bool handled = false;
        if (track->attribute == SVG_ANIM_ATTR_FILL &&
            item->value.kind == SVG_ANIM_VALUE_COLOR) {
            if (document->colors == NULL) return false;
            size_t start = document->shape_edge_start[shape];
            size_t count = document->shape_edge_count[shape];
            if (start > document->edge_count || count > document->edge_count - start)
                return false;
            if (!consume_work(work, count)) return false;
            for (size_t edge = start; edge < start + count; ++edge)
                memcpy(document->colors + edge * 4U, item->value.rgba, 4U);
            handled = true;
        } else if (track->attribute == SVG_ANIM_ATTR_STROKE &&
                   item->value.kind == SVG_ANIM_VALUE_COLOR) {
            if (document->strokes == NULL) return false;
            memcpy(document->strokes[shape].rgba, item->value.rgba, 4U);
            handled = true;
        } else if (track->attribute == SVG_ANIM_ATTR_OPACITY ||
                   track->attribute == SVG_ANIM_ATTR_FILL_OPACITY) {
            if (item->value.kind != SVG_ANIM_VALUE_NUMBER || document->colors == NULL)
                return false;
            double opacity = item->value.number[0];
            scale_unit(&opacity);
            size_t start = document->shape_edge_start[shape];
            size_t count = document->shape_edge_count[shape];
            if (start > document->edge_count || count > document->edge_count - start)
                return false;
            if (!consume_work(work, count)) return false;
            for (size_t edge = start; edge < start + count; ++edge) {
                uint8_t *alpha = &document->colors[edge * 4U + 3U];
                *alpha = (uint8_t)floor((double)*alpha * opacity + 0.5);
            }
            if (track->attribute == SVG_ANIM_ATTR_OPACITY && document->strokes != NULL) {
                uint8_t *alpha = &document->strokes[shape].rgba[3];
                *alpha = (uint8_t)floor((double)*alpha * opacity + 0.5);
            }
            handled = true;
        } else if (track->attribute == SVG_ANIM_ATTR_STROKE_OPACITY) {
            if (item->value.kind != SVG_ANIM_VALUE_NUMBER || document->strokes == NULL)
                return false;
            double opacity = item->value.number[0];
            scale_unit(&opacity);
            uint8_t *alpha = &document->strokes[shape].rgba[3];
            *alpha = (uint8_t)floor((double)*alpha * opacity + 0.5);
            handled = true;
        } else if (track->attribute == SVG_ANIM_ATTR_STROKE_WIDTH ||
                   track->attribute == SVG_ANIM_ATTR_STROKE_DASHOFFSET) {
            if (item->value.kind != SVG_ANIM_VALUE_NUMBER || document->strokes == NULL ||
                (track->attribute == SVG_ANIM_ATTR_STROKE_WIDTH &&
                 item->value.number[0] < 0.0) ||
                fabs(item->value.number[0]) > 1000000.0)
                return false;
            if (track->attribute == SVG_ANIM_ATTR_STROKE_WIDTH)
                document->strokes[shape].width = item->value.number[0];
            else document->strokes[shape].dash_offset = item->value.number[0];
            handled = true;
        } else if (track->attribute == SVG_ANIM_ATTR_X ||
                   track->attribute == SVG_ANIM_ATTR_Y ||
                   track->attribute == SVG_ANIM_ATTR_WIDTH ||
                   track->attribute == SVG_ANIM_ATTR_HEIGHT ||
                   track->attribute == SVG_ANIM_ATTR_CX ||
                   track->attribute == SVG_ANIM_ATTR_CY ||
                   track->attribute == SVG_ANIM_ATTR_R ||
                   track->attribute == SVG_ANIM_ATTR_RX ||
                   track->attribute == SVG_ANIM_ATTR_RY) {
            geom_affine matrix;
            bool effect_limited = false;
            if (!shape_has_animated_effect_limit(document, shape, work,
                                                 &effect_limited) ||
                effect_limited) return false;
            if (!matrix_for_numeric(document, shape, track, &item->value,
                                    world_transforms[shape], &matrix, work) ||
                (svg_shape_paint_for_shape(document, shape) != NULL &&
                 svg_shape_paint_for_shape(document, shape)->kind ==
                    SVG_SHAPE_PAINT_PATTERN) ||
                !apply_geometry_matrix(document, shape, matrix, work) ||
                !refresh_object_paint_bounds(document, shape,
                                             world_transforms[shape], work) ||
                (document->has_clips && document->clips != NULL &&
                 !raster_animation_clips_update(document, shape, true, work,
                                                ANIMATION_TRANSFORM_WORK_MAX)))
                return false;
            handled = true;
        }
        if (!handled) return false;
    }
    return !descendant_found || direct_found;
}

