            .unwrap_err()
            .kind,
        ErrorKind::Limit(LimitKind::Animation)
    );
    assert_eq!(frame.memory_stats(), before);
    assert_eq!(frame.view().clips[0].bounds, bounds);
    assert_eq!(fixture.graph.root().clips[0].bounds, [1.0, 1.0, 9.0, 9.0]);
