struct DuringSuffix {
    saw_edge: bool,
    shapes_after_edge: usize,
    stop_after: Option<usize>,
}
impl WorkControl for DuringSuffix {
    fn charge(&mut self, kind: WorkKind, _: u64) -> Result<(), Stop> {
