            if self.stop_after == Some(self.shapes_after_edge) {
                return Err(Stop::Canceled);
            }
            self.shapes_after_edge += 1;
        }
        Ok(())
    }
    fn checkpoint(&mut self) -> Result<(), Stop> {
        Ok(())
    }
}
